        this.durableLog = [];
        this.pendingLog = [];
    }
    /**
     * 模拟掉电：没 fsync 的东西全部消失。
     * nextPageId 保留，因为真实系统重启后会从元数据里读回它。
     */
    crash() {
        this.pending.clear();
        this.pendingLog = [];
    }
}

